/**
 * THESIS: measurement error is a manufacturing tolerance, so draw it the way a shop
 *   drawing does. Refuses the category default — a shaded band with the explanation
 *   typeset inside it — because that arrangement asks the room to read a paragraph
 *   where a drawing would let them read a dimension.
 * OWN-WORLD: a blueprint. Deep forest sheet, mint hairlines at drafting weight, 45°
 *   section hatch in mid green, condensed all-caps annotation tracked wide, a ruled
 *   notes column down the left and a title block across the foot. Baylor gold is spent
 *   once, on the tolerance dimension. Recognisable with every word removed.
 * STORY: the room sees a dimensioned zone before it sees a claim; understands that a
 *   reading inside it is not an observation; and leaves knowing the second line — the
 *   threshold — is drawn dashed because a person sets it.
 * FIRST VIEWPORT: notes column left, gold tolerance dimension over a hatched zone
 *   centred on the baseline, two readings called out below the axis, general notes
 *   ruled across the foot, title block carrying the claim bottom-left.
 * FORM: the tolerance drawing — candidate 6 of the ordered structural list. Seed key
 *   24b50457.
 * FINISH: unreviewed and undocumented is unfinished; this build ends with the finish
 *   review, the verdict, and DESIGN.md
 */
const pptxgen = require("pptxgenjs");
const path = require("path");
const { C, F } = require("./_kit");
const deck = require("./data-to-decision");

const HAIR = 0.012;                 // a drafting hairline, in inches
const B = { x0: 0.30, y0: 0.26, x1: 9.70, y1: 5.36 };

// Every straight line on this sheet is a filled rect. pptxgenjs 4 writes a 1pt #333333
// outline onto any shape that asks for no border, so nothing here asks for one.
function line(s, { x, y, w, h, color }) {
  s.addShape("rect", { x, y, w, h, fill: { color }, line: { color, width: 0.25 } });
}
const hrule = (s, x, y, w, color) => line(s, { x, y, w, h: HAIR, color });
const vrule = (s, x, y, h, color) => line(s, { x, y, w: HAIR, h, color });

/** A drafting arrowhead. `dir` is the direction it points. */
function arrow(s, { x, y, dir, color, size = 0.11 }) {
  const rotate = dir === "left" ? 270 : dir === "right" ? 90 : 0;
  s.addShape("triangle", {
    x: x - size / 2, y: y - size / 2, w: size, h: size,
    fill: { color }, line: { color, width: 0.25 }, rotate,
  });
}

/** 45° section hatch, clipped to the rect. Drafting says "this region is excluded". */
function hatch(s, { x, y, w, h, step = 0.115, color }) {
  for (let k = -h; k < w; k += step) {
    const t0 = Math.max(-k, 0);
    const t1 = Math.min(w - k, h);
    if (t1 - t0 < 0.02) continue;
    s.addShape("line", {
      x: x + k + t0, y: y + t0, w: t1 - t0, h: t1 - t0,
      line: { color, width: 0.6 },
    });
  }
}

function label(s, text, { x, y, w, color, size = 7, align = "left", face = F.COND }) {
  s.addText(text.toUpperCase(), {
    x, y, w, h: 0.16, fontSize: size, fontFace: face, color, align,
    charSpacing: 1.1, valign: "top", margin: 0,
  });
}

function body(s, text, { x, y, w, h, color = C.MINT, size = 7.5 }) {
  s.addText(text, {
    x, y, w, h, fontSize: size, fontFace: F.BODY_LIGHT, color,
    valign: "top", margin: 0, lineSpacingMultiple: 1.14,
  });
}

// ── the measurement axis ───────────────────────────────────────────────────────
const AX0 = 2.90, AX1 = 9.20, SPAN = 14;           // −7 % … +7 %
const U = (AX1 - AX0) / SPAN;
const ZERO = AX0 + 7 * U;
const xOf = (pct) => ZERO + pct * U;
const AY = 2.90;                                    // axis line
const ZTOP = 1.70;                                  // tolerance zone, top
const XA = xOf(-3), XB = xOf(3);
const COL = { x: 0.46, w: 1.94, divider: 2.56 };    // the notes column

async function build(outPath) {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "Baylor Athletics · Applied Performance";
  pres.title = "Data to Decision — slide 3, tolerance drawing";

  const s = pres.addSlide();
  s.background = { color: C.GROUND_DARK };

  // ── sheet frame ──────────────────────────────────────────────────────────────
  hrule(s, B.x0, B.y0, B.x1 - B.x0, C.MID_GREEN);
  hrule(s, B.x0, B.y1, B.x1 - B.x0, C.MID_GREEN);
  vrule(s, B.x0, B.y0, B.y1 - B.y0, C.MID_GREEN);
  vrule(s, B.x1, B.y0, B.y1 - B.y0, C.MID_GREEN);
  hrule(s, B.x0, 0.82, B.x1 - B.x0, C.MID_GREEN);
  vrule(s, COL.divider, 0.94, 2.98, C.MID_GREEN);

  label(s, "Measurement tolerance — before a number is allowed to mean something",
    { x: 0.46, y: 0.48, w: 6.2, color: C.MINT, size: 8 });
  label(s, "Sheet 3 of 5 · rev A",
    { x: 6.9, y: 0.48, w: 2.66, color: C.MINT, size: 8, align: "right" });

  // ── notes column ─────────────────────────────────────────────────────────────
  label(s, "Inside the hatched zone", { x: COL.x, y: 1.02, w: COL.w, color: C.MINT_SOFT, size: 8.5, face: F.COND_MED });
  body(s, "Not distinguishable from running the test twice. Acting here is a false positive with a real cost.",
    { x: COL.x, y: 1.22, w: COL.w, h: 0.76 });

  hrule(s, COL.x, 2.04, COL.w, C.MID_GREEN);
  label(s, "The dashed line — adj.", { x: COL.x, y: 2.12, w: COL.w, color: C.MINT_SOFT, size: 8.5, face: F.COND_MED });
  body(s, "The threshold is set by which of the two errors costs more here. Not by the statistic.",
    { x: COL.x, y: 2.32, w: COL.w, h: 0.76 });

  hrule(s, COL.x, 3.16, COL.w, C.MID_GREEN);
  label(s, "Source", { x: COL.x, y: 3.24, w: COL.w, color: C.MINT, size: 7 });
  body(s, "Rebelo et al., Sports Medicine 2026 — CV 3.0 %, ICC 0.96.",
    { x: COL.x, y: 3.38, w: COL.w, h: 0.40, size: 7 });

  // ── tolerance zone ───────────────────────────────────────────────────────────
  hatch(s, { x: XA, y: ZTOP, w: XB - XA, h: AY - ZTOP, color: C.MID_GREEN });
  hrule(s, XA, ZTOP, XB - XA, C.MINT);
  vrule(s, XA, 1.36, 3.02 - 1.36, C.MINT);           // extension lines run past
  vrule(s, XB, 1.36, 3.02 - 1.36, C.MINT);

  // the dimension itself — the one gold object on the sheet
  hrule(s, XA + 0.06, 1.46, XB - XA - 0.12, C.GOLD);
  arrow(s, { x: XA + 0.07, y: 1.466, dir: "left", color: C.GOLD });
  arrow(s, { x: XB - 0.07, y: 1.466, dir: "right", color: C.GOLD });
  s.addText("TYPICAL ERROR   ± 3.0 %", {
    x: XA - 0.9, y: 1.00, w: XB - XA + 1.8, h: 0.26, fontSize: 15, fontFace: F.COND,
    bold: true, color: C.GOLD, align: "center", charSpacing: 1.6, valign: "top", margin: 0,
  });
  label(s, "Coefficient of variation of the protocol · ICC 0.96",
    { x: XA - 1.2, y: 1.25, w: XB - XA + 2.4, color: C.MINT, size: 7.5, align: "center" });

  // ── decision threshold: dashed, because a person sets it ─────────────────────
  [xOf(-4.5), xOf(4.5)].forEach((xt) => {
    for (let y = ZTOP + 0.03; y < AY - 0.02; y += 0.13) vrule(s, xt, y, 0.075, C.MINT_SOFT);
    hrule(s, xt - 0.24, 2.30, 0.48, C.MINT_SOFT);
    arrow(s, { x: xt - 0.24, y: 2.306, dir: "left", color: C.MINT_SOFT, size: 0.09 });
    arrow(s, { x: xt + 0.24, y: 2.306, dir: "right", color: C.MINT_SOFT, size: 0.09 });
    label(s, "adj.", { x: xt + 0.30, y: 2.06, w: 0.50, color: C.MINT_SOFT, size: 6.5 });
  });

  // ── axis ─────────────────────────────────────────────────────────────────────
  line(s, { x: 2.80, y: AY, w: 9.32 - 2.80, h: 0.014, color: C.MINT });
  for (let p = -7; p <= 7; p += 1) vrule(s, xOf(p), AY, p % 2 === 0 ? 0.09 : 0.05, C.MINT);
  label(s, "−4%", { x: xOf(-4) - 0.35, y: 2.99, w: 0.70, color: C.MINT, size: 7.5, align: "center" });
  label(s, "+4%", { x: xOf(4) - 0.35, y: 2.99, w: 0.70, color: C.MINT, size: 7.5, align: "center" });
  label(s, "0 · baseline", { x: ZERO - 0.70, y: 2.99, w: 1.40, color: C.MINT, size: 7.5, align: "center" });

  // ── the two readings ─────────────────────────────────────────────────────────
  function reading(pct, { tone, noteX, noteW, title, text }) {
    const x = xOf(pct);
    vrule(s, x, 2.40, AY - 2.40, tone);
    s.addShape("rect", {
      x: x - 0.045, y: AY - 0.045, w: 0.09, h: 0.09,
      fill: { color: tone }, line: { color: tone, width: 0.25 },
    });
    vrule(s, x, AY + 0.04, 3.18 - AY - 0.04, tone);            // leader, dogleg
    const lx = Math.min(x, noteX), lw = Math.abs(x - noteX) + HAIR;
    hrule(s, lx, 3.18, lw, tone);
    vrule(s, noteX, 3.18, 0.06, tone);
    label(s, title, { x: noteX, y: 3.26, w: noteW, color: tone, size: 9, face: F.COND_MED });
    body(s, text, { x: noteX, y: 3.44, w: noteW, h: 0.48, size: 8 });
  }
  reading(-6, {
    tone: C.WHITE, noteX: 2.80, noteW: 2.50,
    title: "Reading B   −6.0 %",
    text: "Clears the floor. Only now does the second question apply — is it big enough to act on for this athlete?",
  });
  reading(-2, {
    tone: C.MINT, noteX: 6.10, noteW: 2.86,
    title: "Reading A   −2.0 %",
    text: "Inside the floor. Nothing has been observed yet.",
  });

  // ── general notes ────────────────────────────────────────────────────────────
  hrule(s, 0.46, 3.98, 9.08, C.MID_GREEN);
  const NOTES = [
    ["Note 1", "Readings shown are illustrative. The ± 3.0 % tolerance is measured, not assumed."],
    ["Note 2", "Two ways to be wrong, and they do not cost the same. Call a change real when it is not and you have made a training change nobody needed. Miss a real one and an at-risk athlete keeps training."],
    ["Note 3", "± 1 SD appears in the paper as one example of a sensitive setting, not as a standard."],
  ];
  NOTES.forEach(([tag, text], i) => {
    const x = 0.46 + i * 3.12;
    label(s, tag, { x, y: 4.04, w: 1.2, color: C.MINT_SOFT, size: 7 });
    body(s, text, { x, y: 4.19, w: 2.84, h: 0.50, size: 7 });
  });

  // ── title block ──────────────────────────────────────────────────────────────
  const TB = 4.74;
  hrule(s, B.x0, TB, B.x1 - B.x0, C.MID_GREEN);
  vrule(s, 5.55, TB, B.y1 - TB, C.MID_GREEN);
  vrule(s, 7.70, TB, B.y1 - TB, C.MID_GREEN);

  label(s, "Title", { x: 0.46, y: 4.80, w: 2.0, color: C.MINT, size: 6.5 });
  s.addText("First the noise floor. Then the decision.", {
    x: 0.46, y: 4.94, w: 5.0, h: 0.34, fontSize: 20, fontFace: F.COND_MED,
    color: C.WHITE, valign: "top", margin: 0,
  });

  label(s, "Subject", { x: 5.71, y: 4.80, w: 1.9, color: C.MINT, size: 6.5 });
  s.addText(deck.topic, {
    x: 5.71, y: 4.92, w: 1.9, h: 0.22, fontSize: 12, fontFace: F.COND_MED,
    color: C.MINT_SOFT, valign: "top", margin: 0,
  });
  s.addText("Baylor Athletics · Applied Performance", {
    x: 5.71, y: 5.13, w: 1.9, h: 0.20, fontSize: 7, fontFace: F.BODY_LIGHT,
    color: C.MINT, valign: "top", margin: 0,
  });

  label(s, "Sheet", { x: 7.86, y: 4.80, w: 1.7, color: C.MINT, size: 6.5 });
  s.addText("3 / 5", {
    x: 7.86, y: 4.90, w: 1.7, h: 0.34, fontSize: 24, fontFace: F.COND,
    color: C.MINT_SOFT, valign: "top", margin: 0, charSpacing: 1,
  });

  s.addNotes(deck.insight.notes);

  await pres.writeFile({ fileName: outPath });
  return outPath;
}

const out = path.resolve(process.argv[2]
  || path.join(__dirname, "..", "build", "Data_to_Decision_S3_ToleranceDrawing.pptx"));
build(out).then((p) => console.log("ok   ", p)).catch((e) => {
  console.error("FAIL ", e.message);
  process.exit(1);
});

