  }
  reading(-6, {
    tone: C.WHITE, noteX: 2.80, noteW: 2.50,
    title: "Reading B   −6.0 %",
    text: "Clears the floor. Only now does the second question apply — is it big enough to act on for this athlete?",
  });
  reading(-2, {
    tone: C.MINT, noteX: 6.10, noteW: 2.86,
    title: "Reading A   −2.0 %",
    text: "Inside the floor. Nothing has been observed yet.",
  });

  // ── general notes ────────────────────────────────────────────────────────────
  hrule(s, 0.46, 3.98, 9.08, C.MID_GREEN);
  const NOTES = [
    ["Note 1", "Readings shown are illustrative. The ± 3.0 % tolerance is measured, not assumed."],
    ["Note 2", "Two ways to be wrong, and they do not cost the same. Call a change real when it is not and you have made a training change nobody needed. Miss a real one and an at-risk athlete keeps training."],
    ["Note 3", "± 1 SD appears in the paper as one example of a sensitive setting, not as a standard."],
  ];
  NOTES.forEach(([tag, text], i) => {
    const x = 0.46 + i * 3.12;
    label(s, tag, { x, y: 4.04, w: 1.2, color: C.MINT_SOFT, size: 7 });
    body(s, text, { x, y: 4.19, w: 2.84, h: 0.50, size: 7 });
  });

  // ── title block ──────────────────────────────────────────────────────────────
  const TB = 4.74;
  hrule(s, B.x0, TB, B.x1 - B.x0, C.MID_GREEN);
  vrule(s, 5.55, TB, B.y1 - TB, C.MID_GREEN);
  vrule(s, 7.70, TB, B.y1 - TB, C.MID_GREEN);

  label(s, "Title", { x: 0.46, y: 4.80, w: 2.0, color: C.MINT, size: 6.5 });
  s.addText("First the noise floor. Then the decision.", {
    x: 0.46, y: 4.94, w: 5.0, h: 0.34, fontSize: 20, fontFace: F.COND_MED,
    color: C.WHITE, valign: "top", margin: 0,
  });

  label(s, "Subject", { x: 5.71, y: 4.80, w: 1.9, color: C.MINT, size: 6.5 });
  s.addText(deck.topic, {
    x: 5.71, y: 4.92, w: 1.9, h: 0.22, fontSize: 12, fontFace: F.COND_MED,
    color: C.MINT_SOFT, valign: "top", margin: 0,
  });
  s.addText("Baylor Athletics · Applied Performance", {
    x: 5.71, y: 5.13, w: 1.9, h: 0.20, fontSize: 7, fontFace: F.BODY_LIGHT,
    color: C.MINT, valign: "top", margin: 0,
  });

  label(s, "Sheet", { x: 7.86, y: 4.80, w: 1.7, color: C.MINT, size: 6.5 });
  s.addText("3 / 5", {
    x: 7.86, y: 4.90, w: 1.7, h: 0.34, fontSize: 24, fontFace: F.COND,
    color: C.MINT_SOFT, valign: "top", margin: 0, charSpacing: 1,
  });

  s.addNotes(deck.insight.notes);

  await pres.writeFile({ fileName: outPath });
  return outPath;
}

const out = path.resolve(process.argv[2]
  || path.join(__dirname, "..", "build", "Data_to_Decision_S3_ToleranceDrawing.pptx"));
build(out).then((p) => console.log("ok   ", p)).catch((e) => {
  console.error("FAIL ", e.message);
  process.exit(1);
});

