=== _kit.js ===
/**
 * Baylor deck kit — the 5 Slides in 5 Minutes renderer, in Baylor brand.
 *
 * Structure follows five-slides-generator's `references/code-template.md`; the palette,
 * type, and contrast rules come from the department's own design system in
 * DEV/TechEd_Prop/ShitfWave/DESIGN.md rather than the template's generic placeholder
 * colours. Deck content lives in the sibling files as pure data — this file owns how a
 * slide looks, those files own what it says.
 *
 * Slides alternate dark / light / dark / light / dark. That alternation is the visual
 * signature of the series and is not a per-deck choice.
 */

const pptxgen = require("pptxgenjs");

// ── Palette ────────────────────────────────────────────────────────────────
// Transcribed from DESIGN.md, including the contrast ratios it measured. The two
// rules below are the ones that get broken by instinct, so they are stated here
// and enforced by the helpers rather than left to memory.
const C = {
  GROUND_DARK: "0B2A1F",  // deep forest — dark slide ground
  GROUND_LIGHT: "F4F2EC", // bone — light slide ground
  PANEL: "103827",        // elevated green — raised panels on dark
  MID_GREEN: "1E6349",    // mid green — the only fill that reads as a bar on the forest
                          // ground. PANEL sits ~2 shades off it and disappears.
  WELL: "07211A",         // deepest green — inset wells
  GREEN: "154734",        // Baylor green — structural ink on light
  GOLD: "FFB81C",         // Baylor gold — DARK GROUNDS ONLY (1.7:1 on bone)
  GOLD_INK: "9A8033",     // antique gold — light-ground gold, hairlines
  MINT: "AFD2C0",         // pale mint — secondary text on dark, ~9:1
  MINT_SOFT: "E4F0E9",    // mint surface — body copy on dark
  BONE_LINE: "E0DDD1",    // hairlines on light
  WHITE: "FFFFFF",
  GRAY_INK: "4E5150",     // gray-green — LIGHT GROUNDS ONLY (too dark on forest)
};

// ── Type ───────────────────────────────────────────────────────────────────
// Family names read from the OTFs in DEV/Baylor_Fonts with fontTools, not guessed.
// "DIN Pro Cond" + bold:true resolves to the Bold subfamily; "DIN Pro Cond Medium"
// is its own family and must be named in full.
const F = {
  DISPLAY: "Baylor Bears Font", // exactly one line per deck — slide 1 only
  COND: "DIN Pro Cond",
  COND_MED: "DIN Pro Cond Medium",
  BODY: "DIN Pro",
  BODY_LIGHT: "DIN Pro Light",
};

const W = 10, H = 5.625;         // LAYOUT_16x9, inches
const M = 0.55;                  // outer margin

// Tracking steps the incumbent site actually uses (.1em–.22em). pptxgenjs takes
// charSpacing in points, so these are the em steps converted at the label size.
const track = (pt, em) => pt * em;

const shadow = () => ({ type: "outer", blur: 10, offset: 3, angle: 135, color: "000000", opacity: 0.28 });

/**
 * Filled rectangle with no visible edge.
 *
 * pptxgenjs 4 ignores `line: { none: true }` and writes a 1pt #333333 outline instead,
 * which turns every hairline and bar into a grey-bordered box. `line: { type: "none" }`
 * emits an empty <a:ln/> that then inherits whatever the theme specifies. The only
 * reliable answer is to draw the edge in the fill colour, so it cannot be seen whether
 * PowerPoint honours it or not. Caught by tools/deck_qa.py, not by the build.
 */
function rect(s, opts) {
  // A caller that asks for a real border gets one. Only the default is overridden —
  // the first version forced the fill colour onto every shape and silently erased the
  // gold border that marks the "does not survive" card in stateSplit.
  const wants = opts.line && !opts.line.none;
  const c = opts.fill && opts.fill.color;
  const line = wants ? opts.line : { color: c, width: 0.4 };
  s.addShape("rect", { ...opts, line });
}

// ── Chrome ─────────────────────────────────────────────────────────────────

/** Micro-label: uppercase, condensed, tracked. The series' signature move. */
function microLabel(s, text, { x, y, w, color, align = "left", size = 9 }) {
  s.addText(String(text).toUpperCase(), {
    x, y, w, h: 0.26, fontSize: size, fontFace: F.COND_MED, color,
    charSpacing: track(size, 0.16), align, valign: "middle", margin: 0,
  });
}

/** Footer band, slide number, and the two micro-labels along the top. */
function frame(s, { dark, topic, n }) {
  const ink = dark ? C.MINT : C.GRAY_INK;
  const accent = dark ? C.GOLD : C.GOLD_INK;

  const labelW = (W - M * 2 - 0.3) / 2;   // the 0.3in gutter keeps the boxes apart
  microLabel(s, "5 slides · 5 minutes", { x: M, y: 0.30, w: labelW, color: accent });
  microLabel(s, topic, { x: W - M - labelW, y: 0.30, w: labelW, color: ink, align: "right" });

  // Hairline under the header. Structural, not decorative — it sets the top of the
  // type column that every slide hangs from.
  rect(s, {
    x: M, y: 0.66, w: W - M * 2, h: 0.012,
    fill: { color: dark ? C.GOLD_INK : C.BONE_LINE },
  });

  rect(s, {
    x: M, y: H - 0.62, w: W - M * 2, h: 0.012,
    fill: { color: dark ? C.GOLD_INK : C.BONE_LINE },
  });
  microLabel(s, "Baylor Athletics · Applied Performance", { x: M, y: H - 0.52, w: 6, color: ink, size: 8 });
  microLabel(s, `${n} / 5`, { x: W - M - 2, y: H - 0.52, w: 2, color: accent, align: "right", size: 8 });
}

function newSlide(pres, { dark, topic, n }) {
  const s = pres.addSlide();
  s.background = { color: dark ? C.GROUND_DARK : C.GROUND_LIGHT };
  frame(s, { dark, topic, n });
  return s;
}

// ── Data visuals ───────────────────────────────────────────────────────────
// Drawn as native PowerPoint shapes rather than rasterised images, so the numbers
// stay editable in the file and nothing goes soft on a projector. One visual per
// deck, on slide 3, encoding a real number from the brief.

/**
 * Ranked horizontal bars against a shared scale.
 *
 * Three fixed columns — label, bar track, value — rather than letting the value text
 * start wherever the bar happens to end. The first version did the latter and the
 * longest bar pushed its own value 0.28in off the right edge of the slide, which the
 * build reported as success. Fixed columns make that impossible by construction.
 */
function barPair(s, { x, y, w, rows, dark, max }) {
  // Four is the ceiling. Five rows plus a footnote collided on the first build, and
  // more importantly a chart with six bars stops being the one picture on the slide.
  // If a deck needs more, the extra rows belong in the footnote or the talking points.
  if (rows.length > 4) {
    throw new Error(`barPair got ${rows.length} rows; 4 is the maximum — move the rest to the footnote`);
  }
  // DESIGN.md, learned the hard way on the protocol card: gold marks what the reader
  // navigates by, not every value. When it spread to all twenty durations it became
  // noise and buried the names. Two accents is the ceiling here for the same reason.
  const accents = rows.filter((r) => r.accent).length;
  if (accents > 2) {
    throw new Error(`barPair got ${accents} gold bars; 2 is the maximum — gold marks the point, not every value`);
  }

  const ink = dark ? C.MINT_SOFT : C.GREEN;
  const sub = dark ? C.MINT : C.GRAY_INK;
  const top = max || Math.max(...rows.map((r) => Math.abs(r.value)));

  const labelW = w * 0.34;
  const trackX = x + w * 0.36;
  const trackW = w * 0.30;          // the longest bar can never exceed this
  const valueX = x + w * 0.68;
  const valueW = w * 0.32;

  let cy = y;
  rows.forEach((r) => {
    const len = Math.max(0.05, (Math.abs(r.value) / top) * trackW);
    s.addText(r.label, {
      x, y: cy, w: labelW, h: 0.3, fontSize: 12, fontFace: F.COND_MED,
      color: sub, align: "left", valign: "middle", margin: 0,
    });
    rect(s, {
      x: trackX, y: cy + 0.06, w: len, h: 0.19,
      fill: { color: r.accent ? (dark ? C.GOLD : C.GOLD_INK) : (dark ? C.MID_GREEN : C.BONE_LINE) },
    });
    s.addText(r.display, {
      x: valueX, y: cy, w: valueW, h: 0.3,
      fontSize: 12.5, fontFace: F.COND, bold: r.accent,
      color: r.accent ? (dark ? C.GOLD : C.GOLD_INK) : ink,
      align: "left", valign: "middle", margin: 0,
    });
    cy += 0.44;
  });
  return cy;
}

/**
 * Noise band: a horizontal band of measurement error with two changes plotted
 * against it — one inside the band (noise), one outside (signal). The single most
 * useful picture in the whole series, so it is a first-class shape.
 */
function noiseBand(s, { x, y, w, dark, bandLabel, inside, outside }) {
  const h = 0.62;
  const ink = dark ? C.MINT_SOFT : C.GREEN;
  const sub = dark ? C.MINT : C.GRAY_INK;

  // A number line of "how big was the change", left to right. The band covers zero up
  // to the test's own typical error; anything to the right of it has cleared the noise.
  //
  // The first version drew a floating band with two loose tick marks and no axis, and
  // it did not read — the ticks collided with the band label and nothing said what the
  // horizontal direction meant. An axis, a label above rather than inside, and markers
  // taller than the band are what make the metaphor legible from the back of a room.
  const axisY = y + h / 2;
  const bandW = w * 0.44;
  const markIn = x + bandW * 0.62;   // inside the band
  const markOut = x + w * 0.70;      // clear of it

  microLabel(s, bandLabel, { x, y: y - 0.34, w: bandW, color: sub, size: 8.5 });

  rect(s, { x, y, w: bandW, h, fill: { color: dark ? C.PANEL : C.BONE_LINE } });

  // The axis runs the full width so the direction of "bigger" is unambiguous.
  rect(s, {
    x, y: axisY - 0.006, w, h: 0.012,
    fill: { color: dark ? C.GOLD_INK : C.BONE_LINE },
  });
  s.addText("larger change →", {
    x: x + w - 2.2, y: axisY + 0.1, w: 2.2, h: 0.3, fontSize: 9.5,
    fontFace: F.COND_MED, color: sub, align: "right", valign: "top", margin: 0,
  });

  // Markers stand proud of the band on both sides so they read as positions on the
  // axis rather than as marks inside a box.
  rect(s, {
    x: markIn, y: y - 0.16, w: 0.05, h: h + 0.32,
    fill: { color: dark ? C.MINT : C.GRAY_INK },
  });
  rect(s, {
    x: markOut, y: y - 0.16, w: 0.06, h: h + 0.32,
    fill: { color: dark ? C.GOLD : C.GOLD_INK },
  });

  // Caption width follows the column. Fixed 2.9in captions collided the moment the
  // band was handed a narrower region than the full slide.
  const capW = Math.min(2.9, w * 0.40);
  const capY = y + h + 0.30;
  s.addText(inside, {
    x: markIn - capW / 2, y: capY, w: capW, h: 0.86, fontSize: 10,
    fontFace: F.BODY_LIGHT, color: sub, align: "center", valign: "top",
    margin: 0, lineSpacingMultiple: 1.1,
  });
  s.addText(outside, {
    x: markOut - capW / 2, y: capY, w: capW, h: 0.86, fontSize: 10,
    fontFace: F.BODY_LIGHT, color: dark ? C.GOLD : C.GOLD_INK,
    align: "center", valign: "top", margin: 0, lineSpacingMultiple: 1.1,
  });

  return capY + 0.86;
}

/** Two-state diagram: what survives fatigue and what does not. */
function stateSplit(s, { x, y, w, dark, kept, lost }) {
  // Side by side is the better picture: the two states are meant to be compared. But
  // this was written against a full-width slide, and in a narrow column the card heads
  // wrapped onto their own body text. Below the threshold the cards stack instead,
  // which keeps the line length readable at the cost of the direct comparison.
  const SIDE_BY_SIDE_MIN = 3.05;
  const half = (w - 0.5) / 2;
  const stacked = half < SIDE_BY_SIDE_MIN;

  const cardW = stacked ? w : half;
  const cardH = stacked ? 1.28 : 1.62;
  const gap = stacked ? 0.20 : 0.5;
  const headSize = stacked ? 16 : 19;
  const bodySize = stacked ? 10.5 : 11.5;

  const pairs = [
    { ...kept, ok: true, cx: x, cy: y },
    {
      ...lost, ok: false,
      cx: stacked ? x : x + cardW + gap,
      cy: stacked ? y + cardH + gap : y,
    },
  ];

  pairs.forEach((p) => {
    rect(s, {
      x: p.cx, y: p.cy, w: cardW, h: cardH,
      fill: { color: dark ? C.PANEL : C.WHITE },
      line: p.ok ? { none: true } : { color: dark ? C.GOLD : C.GOLD_INK, width: 1.5 },
      shadow: dark ? undefined : shadow(),
    });
    microLabel(s, p.tag, {
      x: p.cx + 0.22, y: p.cy + 0.14, w: cardW - 0.44,
      color: p.ok ? (dark ? C.MINT : C.GRAY_INK) : (dark ? C.GOLD : C.GOLD_INK),
      size: stacked ? 8 : 9,
    });
    s.addText(p.head, {
      x: p.cx + 0.22, y: p.cy + 0.42, w: cardW - 0.44, h: 0.38, fontSize: headSize,
      fontFace: F.COND_MED, color: dark ? C.WHITE : C.GREEN,
      align: "left", valign: "top", margin: 0,
    });
    s.addText(p.body, {
      x: p.cx + 0.22, y: p.cy + 0.80, w: cardW - 0.44, h: cardH - 0.92,
      fontSize: bodySize, fontFace: F.BODY_LIGHT, color: dark ? C.MINT : C.GRAY_INK,
      align: "left", valign: "top", margin: 0, lineSpacingMultiple: 1.1,
    });
  });

  return stacked ? y + cardH * 2 + gap : y + cardH;
}

/**
 * Bind the drawing helpers to a slide and a region.
 *
 * A deck says what kind of visual it needs — bars, a noise band, a two-state split —
 * and this decides how that gets drawn. Content files no longer import drawing code,
 * which is what makes an alternative design direction a new kit rather than a rewrite
 * of five decks. Every helper returns the y it finished at, so the caller can place
 * whatever comes next without guessing.
 */
function visualsFor(s, { x, y, w, dark }) {
  return {
    x, y, w, dark,
    bars: (o) => barPair(s, { x, y, w: w - 1.0, dark, ...o }),
    band: (o) => noiseBand(s, { x, y, w, dark, bandLabel: o.label, ...o }),
    split: (o) => stateSplit(s, { x, y, w, dark, ...o }),
  };
}

// ── Slides ─────────────────────────────────────────────────────────────────

function slideHook(pres, d) {
  const s = newSlide(pres, { dark: true, topic: d.topic, n: 1 });

  // The one Baylor Bears line in the deck. DESIGN.md: never a second one.
  s.addText(d.hook.display, {
    x: M, y: 1.18, w: W - M * 2, h: 1.06, fontSize: 60, fontFace: F.DISPLAY,
    color: C.WHITE, align: "left", valign: "top", margin: 0,
  });
  s.addText(d.hook.accent, {
    x: M, y: 2.30, w: W - M * 2, h: 1.06, fontSize: 60, fontFace: F.DISPLAY,
    color: C.GOLD, align: "left", valign: "top", margin: 0,
  });
  s.addText(d.hook.sub, {
    x: M, y: 3.55, w: W - M * 2 - 1.2, h: 0.9, fontSize: 15, fontFace: F.BODY_LIGHT,
    color: C.MINT, align: "left", valign: "top", margin: 0, lineSpacingMultiple: 1.2,
  });
  s.addNotes(d.hook.notes);
  return s;
}

function slideProblem(pres, d) {
  const s = newSlide(pres, { dark: false, topic: d.topic, n: 2 });
  microLabel(s, "the problem", { x: M, y: 1.02, w: 4, color: C.GOLD_INK });
  s.addText(d.problem.head, {
    x: M, y: 1.34, w: W - M * 2 - 3.5, h: 1.0, fontSize: 30, fontFace: F.COND_MED,
    color: C.GREEN, align: "left", valign: "top", margin: 0, lineSpacingMultiple: 0.95,
  });
  s.addText(d.problem.body, {
    x: M, y: 2.52, w: W - M * 2 - 3.6, h: 2.0, fontSize: 13, fontFace: F.BODY_LIGHT,
    color: C.GRAY_INK, align: "left", valign: "top", margin: 0, lineSpacingMultiple: 1.22,
  });

  // The stat block. One number, given room, on a green plate — the only place a
  // light slide carries a saturated field.
  const px = W - M - 3.05;
  rect(s, {
    x: px, y: 1.28, w: 3.05, h: 2.55,
    fill: { color: C.GREEN }, shadow: shadow(),
  });
  // These two carry their own green fill rather than floating transparently over the
  // plate. Same pixels either way, but it makes the background explicit — gold and mint
  // are legal here because they sit on Baylor green, not on the bone ground, and a text
  // box that declares its own background is one a contrast checker can actually verify.
  s.addText(d.problem.stat, {
    x: px + 0.24, y: 1.52, w: 2.57, h: 1.15, fontSize: 54, fontFace: F.COND,
    bold: true, color: C.GOLD, align: "left", valign: "middle", margin: 0,
    fill: { color: C.GREEN },
  });
  s.addText(d.problem.statCaption, {
    x: px + 0.24, y: 2.66, w: 2.57, h: 1.0, fontSize: 11.5, fontFace: F.BODY_LIGHT,
    color: C.MINT_SOFT, align: "left", valign: "top", margin: 0, lineSpacingMultiple: 1.14,
    fill: { color: C.GREEN },
  });
  s.addNotes(d.problem.notes);
  return s;
}

function slideInsight(pres, d) {
  const s = newSlide(pres, { dark: true, topic: d.topic, n: 3 });
  microLabel(s, "the insight", { x: M, y: 1.02, w: 4, color: C.GOLD });
  s.addText(d.insight.head, {
    x: M, y: 1.30, w: W - M * 2, h: 0.68, fontSize: 32, fontFace: F.COND_MED,
    color: C.WHITE, align: "left", valign: "top", margin: 0, lineSpacingMultiple: 0.95,
  });

  // The visual reports where it actually ended. The first build pinned the footnote to
  // a fixed height instead, and a five-row chart ran straight through it — a collision
  // the build reported as a success. Anything that draws must return its own bottom.
  const bottom = d.insight.visual(visualsFor(s, { x: M, y: 2.42, w: W - M * 2, dark: true }));

  if (d.insight.foot) {
    const footY = Math.max(bottom + 0.18, 4.10);
    const footH = H - 0.70 - footY;
    if (footH < 0.34) {
      throw new Error(
        `insight visual ends at ${bottom.toFixed(2)}in, leaving ${footH.toFixed(2)}in for the ` +
        `footnote — cut a row or shorten the footnote`);
    }
    s.addText(d.insight.foot, {
      x: M, y: footY, w: W - M * 2, h: footH, fontSize: 11, fontFace: F.BODY_LIGHT,
      color: C.MINT, align: "left", valign: "top", margin: 0, lineSpacingMultiple: 1.12,
    });
  }
  s.addNotes(d.insight.notes);
  return s;
}

function slideApply(pres, d) {
  const s = newSlide(pres, { dark: false, topic: d.topic, n: 4 });
  microLabel(s, "on monday", { x: M, y: 1.02, w: 4, color: C.GOLD_INK });
  s.addText(d.apply.head, {
    x: M, y: 1.32, w: W - M * 2, h: 0.62, fontSize: 30, fontFace: F.COND_MED,
    color: C.GREEN, align: "left", valign: "top", margin: 0,
  });

  // One column per specialty. Four is the ceiling — five columns at this width
  // pushes the body copy below a readable size.
  const cols = d.apply.columns;
  const gap = 0.30;
  const cw = (W - M * 2 - gap * (cols.length - 1)) / cols.length;
  cols.forEach((c, i) => {
    const cx = M + i * (cw + gap);
    rect(s, {
      x: cx, y: 2.16, w: cw, h: 0.035, fill: { color: C.GOLD_INK },
    });
    microLabel(s, c.who, { x: cx, y: 2.30, w: cw, color: C.GRAY_INK, size: 8.5 });
    s.addText(c.what, {
      x: cx, y: 2.66, w: cw, h: 1.55, fontSize: 11.5, fontFace: F.BODY_LIGHT,
      color: C.GREEN, align: "left", valign: "top", margin: 0, lineSpacingMultiple: 1.18,
    });
  });

  s.addText(d.apply.rule, {
    x: M, y: 4.32, w: W - M * 2, h: 0.6, fontSize: 14, fontFace: F.COND_MED,
    color: C.GREEN, align: "left", valign: "top", margin: 0,
  });
  s.addNotes(d.apply.notes);
  return s;
}

function slideTakeaway(pres, d) {
  const s = newSlide(pres, { dark: true, topic: d.topic, n: 5 });
  microLabel(s, "the one thing", { x: M, y: 1.02, w: 4, color: C.GOLD });

  rect(s, {
    x: M, y: 1.34, w: 0.055, h: 1.62, fill: { color: C.GOLD },
  });
  s.addText(d.takeaway.oneThing, {
    x: M + 0.32, y: 1.30, w: W - M * 2 - 0.32, h: 1.7, fontSize: 25, fontFace: F.COND_MED,
    color: C.WHITE, align: "left", valign: "top", margin: 0, lineSpacingMultiple: 1.06,
  });

  rect(s, {
    x: M, y: 3.22, w: W - M * 2, h: 1.14,
    fill: { color: C.WELL },
  });
  microLabel(s, "for the room", { x: M + 0.26, y: 3.36, w: 4, color: C.MINT });
  s.addText(d.takeaway.question, {
    x: M + 0.26, y: 3.64, w: W - M * 2 - 0.52, h: 0.62, fontSize: 14,
    fontFace: F.BODY_LIGHT, color: C.MINT_SOFT, italic: true,
    align: "left", valign: "top", margin: 0,
  });
  s.addNotes(d.takeaway.notes);
  return s;
}

// ── Entry point ────────────────────────────────────────────────────────────

async function buildDeck(d, outPath) {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "Baylor Athletics · Applied Performance";
  pres.company = "Baylor Athletics";
  pres.subject = d.coreQuestion;
  pres.title = `${d.title} — 5 Slides in 5 Minutes`;

  slideHook(pres, d);
  slideProblem(pres, d);
  slideInsight(pres, d);
  slideApply(pres, d);
  slideTakeaway(pres, d);

  await pres.writeFile({ fileName: outPath });
  return outPath;
}

module.exports = {
  buildDeck, visualsFor,
  barPair, noiseBand, stateSplit,
  rect, microLabel, shadow, track,
  C, F, W, H, M,
};
