} = require("../_kit");

const SEAM = W * 0.38;      // where the claim panel ends
const PAD = 0.42;
const TOP = 1.16;

function slide(pres, { topic, n, label }) {
  const s = pres.addSlide();
  s.background = { color: C.GROUND_LIGHT };

