  // both grounds share one viewport.
  rect(s, { x: 0, y: 0, w: SEAM, h: H, fill: { color: C.GROUND_DARK } });
  rect(s, { x: SEAM, y: 0, w: 0.028, h: H, fill: { color: C.GOLD } });

  microLabel(s, label, { x: PAD, y: 0.44, w: SEAM - PAD * 2, color: C.GOLD });
