    x: SEAM + PAD, y: 0.44, w: W - SEAM - PAD * 2, color: C.GRAY_INK, align: "right",
  });

  rect(s, { x: SEAM + PAD, y: H - 0.60, w: W - SEAM - PAD * 2, h: 0.008, fill: { color: C.BONE_LINE } });
  microLabel(s, "Baylor Athletics · Applied Performance", {
    x: SEAM + PAD, y: H - 0.50, w: 3.3, color: C.GRAY_INK, size: 8,
  });
