/**
 * THESIS: measurement error is a manufacturing tolerance, so draw it the way a shop
 *   drawing does. Refuses the category default — a shaded band with the explanation
 *   typeset inside it — because that arrangement asks the room to read a paragraph
 *   where a drawing would let them read a dimension.
 * OWN-WORLD: a blueprint. Deep forest sheet, mint hairlines at drafting weight, 45°
 *   section hatch, condensed all-caps annotation tracked wide, a ruled notes column
 *   down the left and a title block across the foot. Baylor gold is spent once, on the
 *   typical-error dimension. Recognisable with every word removed.
 * STORY: the room sees a dimensioned zone before it sees a claim; understands that a
 *   reading inside it is not an observation; and leaves knowing the second line — the
 *   threshold — is drawn dashed because a person sets it.
 * FIRST VIEWPORT: notes column left, gold dimension split at the zero centreline over a
 *   hatched zone, two readings called out below the axis, general notes ruled across
 *   the foot, title block carrying the claim bottom-left.
 * FORM: the tolerance drawing — candidate 6 of the ordered structural list. Seed key
 *   24b50457.
 * FINISH: unreviewed and undocumented is unfinished; this build ends with the finish
 *   review, the verdict, and DESIGN.md
 *
 * Second pass, after the finish review. Type came up off the projection floor, the
 * dimension split at the centreline so a full-span arrow can no longer be misread as
 * one 6 % quantity, the threshold says what it is in words instead of "adj.", the hatch
 * moved to mint so it survives a lit room, and the sheet keeps one grid from header to
 * foot. The slide names its subject two ways on purpose — "typical error" is the
 * measured quantity, "noise floor" is the idea — and never a third.
 */
const pptxgen = require("pptxgenjs");
const path = require("path");
const { C, F } = require("./_kit");
const deck = require("./data-to-decision");

const HAIR = 0.012;                 // a drafting hairline, in inches
const B = { x0: 0.30, y0: 0.26, x1: 9.70, y1: 5.36 };
const DIV_A = 5.55, DIV_B = 7.70;   // the sheet's two vertical divisions, notes to foot

// Every straight line on this sheet is a filled rect. pptxgenjs 4 writes a 1pt #333333
// outline onto any shape that asks for no border, so nothing here asks for one.
function line(s, { x, y, w, h, color }) {
  s.addShape("rect", { x, y, w, h, fill: { color }, line: { color, width: 0.25 } });
}
const hrule = (s, x, y, w, color) => line(s, { x, y, w, h: HAIR, color });
const vrule = (s, x, y, h, color, t = HAIR) => line(s, { x, y, w: t, h, color });

/** A drafting arrowhead. `dir` is the direction it points. */
function arrow(s, { x, y, dir, color, size = 0.12 }) {
  const rotate = dir === "left" ? 270 : dir === "right" ? 90 : 0;
  s.addShape("triangle", {
    x: x - size / 2, y: y - size / 2, w: size, h: size,
    fill: { color }, line: { color, width: 0.25 }, rotate,
  });
}

/** 45° section hatch, clipped to the rect. Drafting says "this region is excluded". */
function hatch(s, { x, y, w, h, step = 0.18, color }) {
  for (let k = -h; k < w; k += step) {
    const t0 = Math.max(-k, 0);
    const t1 = Math.min(w - k, h);
    if (t1 - t0 < 0.02) continue;
    s.addShape("line", {
      x: x + k + t0, y: y + t0, w: t1 - t0, h: t1 - t0,
      line: { color, width: 0.5 },
    });
  }
}

/** A drafting centreline: long dash, short dash, repeat. */
function centreline(s, { x, y0, y1, color }) {
  let y = y0;
  let long = true;
  while (y < y1) {
    const seg = Math.min(long ? 0.17 : 0.05, y1 - y);
    vrule(s, x, y, seg, color);
    y += seg + 0.055;
    long = !long;
  }
}

function label(s, text, { x, y, w, color, size = 8, align = "left", face = F.COND, h = 0.20 }) {
  s.addText(text.toUpperCase(), {
    x, y, w, h, fontSize: size, fontFace: face, color, align,
    charSpacing: 1.1, valign: "top", margin: 0,
  });
}

function body(s, text, { x, y, w, h, color = C.MINT, size = 11 }) {
  s.addText(text, {
    x, y, w, h, fontSize: size, fontFace: F.BODY_LIGHT, color,
    valign: "top", margin: 0, lineSpacingMultiple: 1.12,
  });
}

// ── the measurement axis ───────────────────────────────────────────────────────
const AX0 = 2.90, AX1 = 9.20, SPAN = 14;           // −7 % … +7 %
const U = (AX1 - AX0) / SPAN;
const ZERO = AX0 + 7 * U;
const xOf = (pct) => ZERO + pct * U;
const AY = 2.90;                                    // axis line
const ZTOP = 1.88;                                  // hatched zone, top
const XA = xOf(-3), XB = xOf(3);
const COL = { x: 0.46, w: 1.94, divider: 2.56 };    // the notes column

async function build(outPath) {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "Baylor Athletics · Applied Performance";
  pres.title = "Data to Decision — slide 3, tolerance drawing";

  const s = pres.addSlide();
  s.background = { color: C.GROUND_DARK };

  // ── sheet frame. One grid, header to foot. ───────────────────────────────────
  hrule(s, B.x0, B.y0, B.x1 - B.x0, C.MID_GREEN);
  hrule(s, B.x0, B.y1, B.x1 - B.x0, C.MID_GREEN);
  vrule(s, B.x0, B.y0, B.y1 - B.y0, C.MID_GREEN);
  vrule(s, B.x1, B.y0, B.y1 - B.y0, C.MID_GREEN);
  hrule(s, B.x0, 0.82, B.x1 - B.x0, C.MID_GREEN);
  vrule(s, COL.divider, 0.94, 2.96, C.MID_GREEN);

  label(s, "The noise floor — before a number is allowed to mean something",
    { x: 0.46, y: 0.46, w: 4.4, color: C.MINT, size: 9 });
  label(s, "Data to Decision · 5 Slides in 5 Minutes",
    { x: 6.4, y: 0.46, w: 3.16, color: C.MINT, size: 9, align: "right" });

  // ── notes column ─────────────────────────────────────────────────────────────
  label(s, "Inside the noise floor", { x: COL.x, y: 1.10, w: COL.w, color: C.MINT_SOFT, size: 10, face: F.COND_MED });
  body(s, "Not distinguishable from running the test again.", { x: COL.x, y: 1.32, w: COL.w, h: 0.44 });

  hrule(s, COL.x, 1.86, COL.w, C.MID_GREEN);
  label(s, "The dashed line", { x: COL.x, y: 1.96, w: COL.w, color: C.MINT_SOFT, size: 10, face: F.COND_MED });
  body(s, "Set by which error costs more. Not by the data.", { x: COL.x, y: 2.18, w: COL.w, h: 0.44 });

  hrule(s, COL.x, 2.72, COL.w, C.MID_GREEN);
  label(s, "Source", { x: COL.x, y: 2.82, w: COL.w, color: C.MINT, size: 8 });
  body(s, "Rebelo et al., Sports Medicine 2026.", { x: COL.x, y: 2.99, w: COL.w, h: 0.42, size: 9 });

  // ── the hatched zone ─────────────────────────────────────────────────────────
  hatch(s, { x: XA, y: ZTOP, w: XB - XA, h: AY - ZTOP, color: C.MINT });
  hrule(s, XA, ZTOP, XB - XA, C.MINT_SOFT);
  vrule(s, XA, 1.68, 2.98 - 1.68, C.MINT_SOFT);      // extension lines run past
  vrule(s, XB, 1.68, 2.98 - 1.68, C.MINT_SOFT);

  // ── the dimension. Split at the centreline, so a full-span arrow can never be
  //    read as one 6 % quantity. The one gold element on the sheet. ─────────────
  s.addText("TYPICAL ERROR", {
    x: ZERO - 1.60, y: 1.00, w: 3.20, h: 0.28, fontSize: 15, fontFace: F.COND,
    bold: true, color: C.GOLD, align: "center", charSpacing: 1.6, valign: "top", margin: 0,
  });
  label(s, "CV 3.0 % of the protocol · ICC 0.96",
    { x: ZERO - 2.00, y: 1.29, w: 4.00, color: C.MINT, size: 8.5, align: "center" });

  [[XA, ZERO, "left"], [ZERO, XB, "right"]].forEach(([x0, x1, outward]) => {
    hrule(s, x0 + 0.06, 1.76, x1 - x0 - 0.06, C.GOLD);
    arrow(s, {
      x: outward === "left" ? x0 + 0.07 : x1 - 0.07,
      y: 1.766, dir: outward, color: C.GOLD,
    });
    s.addText("3.0 %", {
      x: (x0 + x1) / 2 - 0.45, y: 1.46, w: 0.90, h: 0.24, fontSize: 11, fontFace: F.COND_MED,
      color: C.GOLD, align: "center", valign: "top", margin: 0,
    });
  });
  vrule(s, ZERO, 1.70, 0.14, C.GOLD);                // the dimension's own origin tick

  // ── the zero datum, drawn as a centreline ────────────────────────────────────
  centreline(s, { x: ZERO, y0: 1.92, y1: 2.94, color: C.MINT_SOFT });

  // ── decision threshold: dashed, because a person sets it ─────────────────────
  [xOf(-4.5), xOf(4.5)].forEach((xt) => {
    for (let y = ZTOP + 0.04; y < AY - 0.02; y += 0.13) vrule(s, xt, y, 0.075, C.MINT_SOFT);
    hrule(s, xt - 0.24, 2.34, 0.48, C.MINT_SOFT);
    arrow(s, { x: xt - 0.24, y: 2.346, dir: "left", color: C.MINT_SOFT, size: 0.10 });
    arrow(s, { x: xt + 0.24, y: 2.346, dir: "right", color: C.MINT_SOFT, size: 0.10 });
  });
  label(s, "Threshold", { x: 8.44, y: 2.08, w: 1.16, color: C.MINT_SOFT, size: 9.5, face: F.COND_MED });
  body(s, "Shown at an arbitrary position. Set by cost, not read off this axis.",
    { x: 8.44, y: 2.27, w: 1.16, h: 0.62, size: 8 });

  // ── axis ─────────────────────────────────────────────────────────────────────
  line(s, { x: 2.80, y: AY, w: 9.32 - 2.80, h: 0.014, color: C.MINT });
  for (let p = -7; p <= 7; p += 1) vrule(s, xOf(p), AY, p % 2 === 0 ? 0.09 : 0.05, C.MINT);
  label(s, "−7 %", { x: xOf(-7) - 0.35, y: 2.99, w: 0.70, h: 0.16, color: C.MINT, size: 9.5, align: "center" });
  label(s, "0", { x: ZERO - 0.25, y: 2.99, w: 0.50, h: 0.16, color: C.MINT, size: 9.5, align: "center" });
  label(s, "+7 %", { x: xOf(7) - 0.35, y: 2.99, w: 0.70, h: 0.16, color: C.MINT, size: 9.5, align: "center" });

  // ── the two readings ─────────────────────────────────────────────────────────
  function reading(pct, { tone, noteX, noteW, title, text, weight }) {
    const x = xOf(pct);
    vrule(s, x, 2.46, AY - 2.46, tone, weight);
    s.addShape("rect", {
      x: x - 0.05, y: AY - 0.05, w: 0.10, h: 0.10,
      fill: { color: tone }, line: { color: tone, width: 0.25 },
    });
    vrule(s, x, AY + 0.04, 3.20 - AY - 0.04, tone);            // leader, dogleg
    hrule(s, Math.min(x, noteX), 3.20, Math.abs(x - noteX) + HAIR, tone);
    vrule(s, noteX, 3.20, 0.06, tone);
    label(s, title, { x: noteX, y: 3.28, w: noteW, color: tone, size: 10, face: F.COND_MED });
    body(s, text, { x: noteX, y: 3.48, w: noteW, h: 0.38, size: 10 });
  }
  reading(-6, {
    tone: C.WHITE, noteX: 2.80, noteW: 2.35, weight: 0.020,
    title: "Reading B   −6.0 %   · illustrative",
    text: "Clears the noise floor. Only now ask if it is worth acting on.",
  });
  reading(-2, {
    tone: C.MINT_SOFT, noteX: 5.45, noteW: 2.60, weight: HAIR,
    title: "Reading A   −2.0 %   · illustrative",
    text: "Inside the noise floor. The test cannot tell this from noise.",
  });

  // ── general notes, on the sheet's own divisions ───────────────────────────────
  hrule(s, B.x0, 3.92, B.x1 - B.x0, C.MID_GREEN);
  vrule(s, DIV_A, 3.92, B.y1 - 3.92, C.MID_GREEN);
  vrule(s, DIV_B, 3.92, B.y1 - 3.92, C.MID_GREEN);

  label(s, "Note 1", { x: 0.46, y: 3.97, w: 1.2, color: C.MINT_SOFT, size: 8 });
  body(s, "Two ways to be wrong, and they do not cost the same. Acting on noise costs a training change nobody needed; missing a real change keeps an at-risk athlete training.",
    { x: 0.46, y: 4.12, w: 4.93, h: 0.42, size: 9.5 });
  label(s, "Note 2", { x: 5.71, y: 3.97, w: 1.2, color: C.MINT_SOFT, size: 8 });
  body(s, "Readings and the threshold position are illustrative.",
    { x: 5.71, y: 4.12, w: 1.83, h: 0.42, size: 9 });
  label(s, "Note 3", { x: 7.86, y: 3.97, w: 1.2, color: C.MINT_SOFT, size: 8 });
  body(s, "± 1 SD is the paper's own example of a sensitive setting, not a standard.",
    { x: 7.86, y: 4.12, w: 1.68, h: 0.42, size: 8.5 });

  // ── title block ──────────────────────────────────────────────────────────────
  const TB = 4.60;
  hrule(s, B.x0, TB, B.x1 - B.x0, C.MID_GREEN);

  label(s, "Title", { x: 0.46, y: 4.65, w: 2.0, color: C.MINT, size: 7.5 });
  s.addText("First the noise floor. Then the decision.", {
    x: 0.46, y: 4.79, w: 5.02, h: 0.54, fontSize: 21, fontFace: F.COND_MED,
    color: C.WHITE, valign: "top", margin: 0, lineSpacingMultiple: 1.02,
  });

  label(s, "Subject", { x: 5.71, y: 4.65, w: 1.9, color: C.MINT, size: 7.5 });
  s.addText(deck.topic, {
    x: 5.71, y: 4.79, w: 1.9, h: 0.22, fontSize: 10, fontFace: F.COND_MED,
    color: C.MINT_SOFT, valign: "top", margin: 0,
  });
  s.addText("Baylor Athletics · Applied Performance", {
    x: 5.71, y: 5.02, w: 1.9, h: 0.20, fontSize: 7.5, fontFace: F.BODY_LIGHT,
    color: C.MINT, valign: "top", margin: 0,
  });

  label(s, "Sheet", { x: 7.86, y: 4.65, w: 1.7, color: C.MINT, size: 7.5 });
  s.addText("3 / 5", {
    x: 7.86, y: 4.79, w: 1.7, h: 0.26, fontSize: 13, fontFace: F.COND,
    color: C.MINT_SOFT, valign: "top", margin: 0, charSpacing: 1,
  });

  s.addNotes(deck.insight.notes);

  await pres.writeFile({ fileName: outPath });
  return outPath;
}

const out = path.resolve(process.argv[2]
  || path.join(__dirname, "..", "build", "Data_to_Decision_S3_ToleranceDrawing.pptx"));
build(out).then((p) => console.log("ok   ", p)).catch((e) => {
  console.error("FAIL ", e.message);
  process.exit(1);
});
